using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
namespace ClearSpace {
public static class RulePackTests {
 public static string Raw(string id="example-pack",string version="1.0.0"){return new JavaScriptSerializer().Serialize(new ApplicationRulePack{Schema=2,PackId=id,Name="Example cache rules",Version=version,Rules=new List<ApplicationRule>{new ApplicationRule{Id="example-logs",Name="Fixture App",MatchNames=new[]{"Fixture App"},ExecutableNames=new[]{"fixture.exe"},Paths=new[]{@"%TEMP%\Clarity110Fixture\Cache"},KeepDays=14,Conditions=new RuleConditions{NamePattern="*.log",MinAgeDays=30,MinSizeBytes=10,MaxSizeBytes=100}}}});}
 public static void Verify(string directory,Action<bool,string> check){
  Func<Action,bool> reject=a=>{try{a();return false;}catch{return true;}};var parser=new RuleStore();var parsed=parser.Read(Raw(),true);check(parsed.Pack.Schema==2&&parsed.Pack.PackId=="example-pack","Schema 2 parses metadata and declarative conditions");check(reject(()=>parser.Read(Raw().Replace("MinSizeBytes","MinSizeByte"),true)),"Unknown condition fields cannot silently weaken a size filter");check(reject(()=>parser.Read(Raw().Replace("example-pack","../escape"),true)),"Pack IDs reject traversal before any storage operation");check(reject(()=>parser.Read(Raw().Replace("\"Schema\":2","\"Schema\":1"),true)),"Schema 1 cannot silently accept Schema 2 conditions");check(reject(()=>parser.Read(Raw().Replace("\"MinAgeDays\":30","\"MinAgeDays\":-1"),true)),"Negative condition ages are rejected");check(reject(()=>parser.Read(Raw().Replace("\"MaxSizeBytes\":100","\"MaxSizeBytes\":1"),true)),"Inverted file size ranges are rejected");check(reject(()=>parser.Read(Raw().Replace("*.log","..\\\\*.log"),true)),"File name glob conditions cannot contain paths");check(reject(()=>parser.Read(Raw().Replace("\"Method\":\"files\"","\"Method\":\"execute\""),true)),"Rule packs cannot supply executable actions");
  var settings=new JavaScriptSerializer().Deserialize<CleanerSettings>("{\"UseWinapp2\":true,\"AutomaticUpdates\":true}");check(settings.Winapp2Enabled&&!settings.JsonEnabled&&settings.AutoWinapp2&&!settings.AutoJson,"Legacy Winapp2 settings migrate without enabling additional rules");settings.UseWinapp2=false;check(settings.Winapp2Enabled&&settings.JsonEnabled&&settings.AutoJson,"Winapp2 defaults on independently of the legacy JSON editor preference");settings.EnableWinapp2=false;check(!settings.Winapp2Enabled,"An explicit Winapp2 opt-out remains respected after migration");settings.EnableWinapp2=settings.EnableJson=true;settings.AutomaticWinapp2=true;settings.AutomaticJson=false;settings.UseWinapp2=true;check(settings.Winapp2Enabled&&settings.JsonEnabled&&settings.AutoWinapp2&&!settings.AutoJson,"Both rule sources have independent enabled and automatic-update settings");settings.UseWinapp2=false;check(settings.Winapp2Enabled&&settings.JsonEnabled,"Viewing another source does not disable either source");
  var catalog=new RulePackCatalog(Path.Combine(directory,"packs"));var entry=catalog.Import(Raw());check(!entry.Enabled&&catalog.List().Count==1,"Installing a rule pack saves definitions and leaves it disabled");catalog.SetEnabled(entry.Id,true);catalog.Import(Raw(version:"1.1.0"));check(catalog.List().Single().Enabled&&catalog.List().Single().CanRollback,"Pack upgrades preserve the enable flag and retain the previous version atomically");check(catalog.Rollback(entry.Id).Loaded.Pack.Version=="1.0.0"&&catalog.List().Single().Enabled,"Pack rollback restores the previous definitions without changing its enable flag");check(catalog.Rollback(entry.Id).Loaded.Pack.Version=="1.1.0","Rollback retains the replaced version for an explicit return");check(reject(()=>catalog.Import(Raw(version:"1.0.0")))&&catalog.List().Single().Loaded.Pack.Version=="1.1.0","Imports cannot silently downgrade an installed rule pack");check(reject(()=>catalog.Import("{broken"))&&catalog.List().Single().Loaded.Pack.Version=="1.1.0","An invalid import preserves the active pack");catalog.SetEnabled(entry.Id,false);check(catalog.Resolve(new DiscoveryResult(),CancellationToken.None).Count==0,"Disabled packs contribute no scan rules");File.WriteAllText(Path.Combine(catalog.DirectoryPath,"broken-pack.json"),"invalid");var errors=new List<string>();check(catalog.List(errors).Count==1&&errors.Count==1,"A damaged pack is skipped and reported without blocking valid packs");check(reject(()=>catalog.Remove("../escape")),"Pack removal validates the ID and cannot remove arbitrary paths");catalog.Remove(entry.Id);check(catalog.List().Count==0,"Removing a rule pack affects only its stored definition");
  var parameters=new CspParameters{ProviderType=24,Flags=CspProviderFlags.CreateEphemeralKey};using(var rsa=new RSACryptoServiceProvider(2048,parameters)){rsa.PersistKeyInCsp=false;byte[] bytes=Encoding.UTF8.GetBytes(Raw());string signed=new JavaScriptSerializer().Serialize(new SignedRuleEnvelope{Payload=Convert.ToBase64String(bytes),Signature=Convert.ToBase64String(rsa.SignData(bytes,CryptoConfig.MapNameToOID("SHA256")))});check(new RuleStore(null,rsa.ToXmlString(false)).Read(signed,false).Pack.Schema==2,"Schema 2 uses the existing publisher signature envelope");check(reject(()=>new RuleStore(null,rsa.ToXmlString(false)).Read(Raw(),false)),"Online Schema 2 rules still require the publisher signature");}
  // A uniquely named, generated cache under TEMP exercises the real C-drive path policy.
  string temp=Path.Combine(Path.GetTempPath(),"Clarity110Fixture-"+Guid.NewGuid().ToString("N")),cache=Path.Combine(temp,"Cache");Directory.CreateDirectory(cache);
  try{
   var pack=parser.Read(Raw().Replace("Clarity110Fixture",Path.GetFileName(temp)),true);var discovery=new DiscoveryResult{Applications=new List<ApplicationIdentity>{new ApplicationIdentity{Name="Fixture App",Executable=Path.Combine(temp,"fixture.exe"),InstallDirectory=temp}}};var rules=RuleCompiler.Resolve(pack,discovery);check(rules.Count==1&&rules[0].Days==30&&!rules[0].Quick&&!rules[0].AllowManual&&rules[0].ForceBackup,"Compiled Schema 2 rules apply the stricter age, stay advanced-only and force backups");
   Action<string,int,int> file=(name,size,days)=>{string p=Path.Combine(cache,name);File.WriteAllText(p,new string('x',size));File.SetLastWriteTimeUtc(p,DateTime.UtcNow.AddDays(-days));};file("selected.log",20,60);file("small.log",5,60);file("large.log",110,60);file("recent.log",20,20);file("wrong.tmp",20,60);file("account.json",20,60);Directory.CreateDirectory(Path.Combine(cache,"Cookies"));file("Cookies\\secret.log",20,60);
   var jsonStore=new RuleStore(Path.Combine(directory,"primary-json"));jsonStore.Import(pack.Raw,true);var iniStore=new Winapp2Store(Path.Combine(directory,"primary-ini"));iniStore.Import("[Fixture App Cache *]\nDetectFile=%Temp%\\"+Path.GetFileName(temp)+"\nFileKey1=%Temp%\\"+Path.GetFileName(temp)+"\\Cache|*.log|RECURSE\n");var emptyPacks=new RulePackCatalog(Path.Combine(directory,"empty-packs"));var sources=new CleanerSettings{EnableWinapp2=true,EnableJson=true};var combined=ExternalRuleSources.Resolve(sources,discovery,CancellationToken.None,null,jsonStore,iniStore,emptyPacks);check(combined.Rules.Any(r=>r.Source==Winapp2Store.Url)&&combined.Rules.Any(r=>r.Id.StartsWith("library-primary-"))&&combined.RuleVersion.Contains("Winapp2")&&combined.RuleVersion.Contains("JSON"),"Regular scanning resolves Winapp2 and JSON together rather than treating the editor as a selector");var together=new Engine(combined.Rules){IsRunning=owners=>false}.Scan(CancellationToken.None,null);check(together.SelectMany(f=>f.Candidates).Count(f=>Path.GetFileName(f.Path)=="selected.log")==1&&together.Sum(f=>f.EligibleBytes)==together.SelectMany(f=>f.Candidates).GroupBy(f=>f.Path,StringComparer.OrdinalIgnoreCase).Sum(g=>g.First().Bytes),"A file shared by Winapp2 and JSON contributes bytes and a deletion candidate once");sources.EnableWinapp2=false;check(ExternalRuleSources.Resolve(sources,discovery,CancellationToken.None,null,jsonStore,iniStore,emptyPacks).Rules.All(r=>r.Id.StartsWith("library-primary-")),"Disabling Winapp2 leaves the JSON source active");sources.EnableJson=false;check(ExternalRuleSources.Resolve(sources,discovery,CancellationToken.None,null,jsonStore,iniStore,emptyPacks).Rules.Count==0,"Both primary sources may be disabled independently of built-in rules");
   var beforeSettings=new JavaScriptSerializer().Serialize(sources);check(reject(()=>RuleSourcePreferences.Save(sources,true,true,true,true,"https://example.test/rules.json",true,()=>{throw new IOException("fixture save failure");}))&&new JavaScriptSerializer().Serialize(sources)==beforeSettings,"A failed settings write restores enabled sources, update flags, editor and address together");check(reject(()=>RuleSourcePreferences.Save(sources,true,true,false,true,"",true,()=>{})),"Automatic JSON checks require an address before changing effective scan settings");
   check(RulePathExpander.Expand(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"Temp",CancellationToken.None).Length==0,"JSON expansion never traverses the excluded Windows directory");check(reject(()=>RulePathExpander.Expand(temp,"*",new CancellationToken(true))),"Cancellation interrupts path expansion before directory traversal");
   var preview=RulePreview.Scan(pack,discovery,CancellationToken.None);var finding=preview.Single();check(finding.Candidates.Count==1&&Path.GetFileName(finding.Candidates[0].Path)=="selected.log","Production preview combines filename, minimum age and size conditions with AND semantics");check(finding.ManualCandidates.Count==0&&Directory.GetFiles(cache,"*",SearchOption.AllDirectories).Length==7,"Preview preserves every file and cannot expose condition failures as manual deletions");
   var engine=new Engine(rules){IsRunning=owners=>false,FileBackupDirectory=Path.Combine(directory,"pack-backups")};var normal=engine.Scan(CancellationToken.None,null);check(normal.Sum(f=>f.EligibleBytes)==preview.Sum(f=>f.EligibleBytes),"Preview and cleanup candidates use the same compiler and evaluator");var second=RuleCompiler.Resolve(parser.Read(Raw("second-pack").Replace("Clarity110Fixture",Path.GetFileName(temp)),true),discovery);engine=new Engine(rules.Concat(second).ToList()){IsRunning=owners=>false,FileBackupDirectory=Path.Combine(directory,"pack-backups")};var duplicates=engine.Scan(CancellationToken.None,null);check(duplicates.Sum(f=>f.Candidates.Count)==1&&duplicates.Sum(f=>f.EligibleBytes)==20,"Overlapping packs count a candidate file and its cleanable bytes only once");var before=File.ReadAllBytes(Path.Combine(cache,"selected.log"));var result=engine.Clean(duplicates,true,CancellationToken.None,null);check(result.Deleted==0,"External rule-pack candidates cannot enter quick cleanup");
   rules[0].Conditions.MinSizeBytes=30;var changed=new Engine(rules){IsRunning=owners=>false,FileBackupDirectory=Path.Combine(directory,"pack-backups")}.Clean(normal,false,CancellationToken.None,null);check(changed.Deleted==0&&File.ReadAllBytes(Path.Combine(cache,"selected.log")).SequenceEqual(before),"Cleanup rechecks file conditions and preserves candidates that no longer match");
   rules[0].Conditions.MinSizeBytes=10;engine=new Engine(rules){IsRunning=owners=>false,FileBackupDirectory=Path.Combine(directory,"pack-backups")};normal=engine.Scan(CancellationToken.None,null);result=engine.Clean(normal,false,CancellationToken.None,null);check(result.Deleted==1&&result.BackupFiles==1&&File.Exists(Path.Combine(cache,"Cookies","secret.log")),"Advanced pack cleanup backs up its match while preserving excluded personal files");check(FileRecovery.Restore(result.FileBackupManifest)==1&&File.ReadAllBytes(Path.Combine(cache,"selected.log")).SequenceEqual(before),"Rule-pack cleanup retains exact-content backup restoration");
   var token=new CancellationToken(true);check(reject(()=>RulePreview.Scan(pack,discovery,token))&&File.Exists(Path.Combine(cache,"selected.log")),"A cancelled preview never deletes cache files");
  }finally{if(Path.GetFullPath(temp).StartsWith(Path.GetFullPath(Path.GetTempPath()).TrimEnd('\\')+"\\Clarity110Fixture-",StringComparison.OrdinalIgnoreCase)&&Engine.SafeAncestors(Path.Combine(temp,"probe")))Directory.Delete(temp,true);}
 }
}
}
